#!/usr/bin/env bash
set -euo pipefail
umask 077
ROOT=/opt/o2o-sp08-a303
NODE="$ROOT/node-v24.22.3/bin/node"
test -x "$NODE"
test "$("$NODE" --version)" = v24.22.3
install -d -m 0700 /opt/o2o-sp08-a303
if [ -e /opt/o2o-sp08-a303/server-code ]; then echo 'existing-server-code'; exit 1; fi
printf '%s' '' | base64 -d > /opt/o2o-sp08-a303/server-code.zip
unzip -q /opt/o2o-sp08-a303/server-code.zip -d /opt/o2o-sp08-a303/server-code
chmod 0700 /opt/o2o-sp08-a303 /opt/o2o-sp08-a303/server-code
chmod 0600 /opt/o2o-sp08-a303/server-code/*.cjs /opt/o2o-sp08-a303/server-code.zip
"$NODE" --version
sha256sum /opt/o2o-sp08-a303/server-code/*.cjs
